// PLAN:
// 1. Setup: Inject NU Brand fonts (Roboto Condensed, Open Sans, IBM Plex Mono) and CSS variables.
// 2. Data Model: Define seed data for Student (Alex), SME Job (Nebula Metrics), and Big Tech Benchmark (Google).
// 3. State Management: Use a main `screen` state to track the 7-step flow, plus `chatHistory`, `isTyping`, and AI response data states.
// 4. AI Integration:
//    - `generate_discovery_alert`: Fetch to `/api/ai/openai` to rewrite the SME JD into a 3-bullet pitch.
//    - `compare_to_big_tech`: Fetch to `/api/ai/gemini-compat` to generate a side-by-side comparison.
//    - Robust JSON parsing to handle LLM markdown wrapping.
// 5. Components:
//    - `App`: Root controller.
//    - `TeamsShell`: The outer layout mimicking MS Teams (Sidebar, Chat List, Main Area).
//    - `ChatFeed`: Renders the conversation history with Framer Motion for message entrance.
//    - `AdaptiveCard`: Reusable container for bot UI, styled with NU brand tokens.
//    - `TypingIndicator`: Animated dots.
//    - `DemoControls`: Top-right panel for reviewers to jump states.
// 6. Micro-interactions: Hover/active states on buttons, staggered fade-ins for card bullets, auto-scroll to bottom of chat.

// --- SEED DATA ---
const SEED_DATA = {
  student: {
    name: "Alex",
    major: "Computer Science",
    interests: "Machine Learning, AI, PyTorch",
    targets: "Google, Tesla, OpenAI"
  },
  smeJob: {
    company: "Nebula Metrics",
    size: "50-person Series A",
    title: "Machine Learning Engineer Co-op",
    originalJD: "Looking for a co-op to assist with data cleaning, pipeline maintenance, and some model training using Python and AWS. Will work closely with the engineering team to support the core product.",
    skills: "PyTorch, AWS, Data Pipelines"
  },
  bigTech: {
    company: "Google",
    role: "ML Software Engineering Intern",
    scope: "Internal dashboards, bug fixes, shadowing",
    limitations: "No direct production deployment, heavy red tape"
  }
};

// --- UTILS ---
const extractJSON = (text) => {
  try {
    const match = text.match(/\{[\s\S]*\}/);
    return match ? JSON.parse(match[0]) : null;
  } catch (e) {
    console.error("Failed to parse JSON", text);
    return null;
  }
};

// --- COMPONENTS ---

const Header = () => (
  <div style={{
    height: '48px',
    backgroundColor: 'var(--nu-surface)',
    borderBottom: '1px solid var(--nu-border)',
    display: 'flex',
    alignItems: 'center',
    padding: '0 16px',
    justifyContent: 'space-between',
    flexShrink: 0
  }}>
    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
      <div style={{ width: '24px', height: '24px', backgroundColor: 'var(--nu-red)', borderRadius: '2px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 'bold', fontSize: '12px', fontFamily: 'var(--font-display)' }}>N</div>
      <span style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: '16px', color: 'var(--nu-text-primary)' }}>NUworks Discovery</span>
    </div>
    <div style={{ display: 'flex', alignItems: 'center', gap: '16px', color: 'var(--nu-text-secondary)' }}>
      <lucide.Search size={18} />
      <lucide.MoreHorizontal size={18} />
      <div style={{ width: '28px', height: '28px', borderRadius: '50%', backgroundColor: 'var(--nu-panel)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '12px', fontWeight: 600 }}>AL</div>
    </div>
  </div>
);

const TeamsSidebar = () => (
  <div style={{
    width: '64px',
    backgroundColor: 'var(--nu-panel)',
    borderRight: '1px solid var(--nu-border)',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    paddingTop: '16px',
    gap: '24px',
    flexShrink: 0
  }}>
    {[
      { icon: lucide.Bell, label: 'Activity' },
      { icon: lucide.MessageSquare, label: 'Chat', active: true },
      { icon: lucide.Users, label: 'Teams' },
      { icon: lucide.Calendar, label: 'Calendar' }
    ].map((item, i) => (
      <div key={i} style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: '4px',
        color: item.active ? 'var(--nu-red)' : 'var(--nu-text-secondary)',
        cursor: 'pointer'
      }}>
        <item.icon size={24} strokeWidth={item.active ? 2.5 : 2} />
        <span style={{ fontSize: '10px', fontFamily: 'var(--font-body)', fontWeight: item.active ? 600 : 400 }}>{item.label}</span>
      </div>
