);

const ChatList = ({ currentScreen, onSelectBot }) => (
  <div style={{
    width: '280px',
    backgroundColor: 'var(--nu-surface)',
    borderRight: '1px solid var(--nu-border)',
    display: 'flex',
    flexDirection: 'column',
    flexShrink: 0
  }}>
    <div style={{ padding: '16px', borderBottom: '1px solid var(--nu-border)' }}>
      <h2 style={{ fontFamily: 'var(--font-display)', fontSize: '20px', margin: 0 }}>Chat</h2>
    </div>
    <div style={{ flex: 1, overflowY: 'auto' }}>
      <div style={{ padding: '12px 16px', display: 'flex', gap: '12px', alignItems: 'center', cursor: 'pointer', backgroundColor: 'var(--nu-bg)' }}>
        <div style={{ width: '40px', height: '40px', borderRadius: '50%', backgroundColor: 'var(--nu-panel)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <lucide.Users size={20} color="var(--nu-text-secondary)" />
        </div>
        <div>
          <div style={{ fontFamily: 'var(--font-body)', fontWeight: 600, fontSize: '14px' }}>Group 4 - CS3500</div>
          <div style={{ fontFamily: 'var(--font-body)', fontSize: '12px', color: 'var(--nu-text-tertiary)' }}>You: I'll push the branch tonight.</div>
        </div>
      </div>

      <div 
        onClick={onSelectBot}
        style={{ 
          padding: '12px 16px', 
          display: 'flex', 
          gap: '12px', 
          alignItems: 'center', 
          cursor: 'pointer', 
          backgroundColor: currentScreen !== 'teams_chat_list' ? 'var(--nu-panel)' : 'var(--nu-bg)',
          borderLeft: currentScreen !== 'teams_chat_list' ? '3px solid var(--nu-red)' : '3px solid transparent'
        }}
      >
        <div style={{ width: '40px', height: '40px', borderRadius: '2px', backgroundColor: 'var(--nu-red)', display: 'flex', alignItems: 'center', justifyContent: 'center', position: 'relative' }}>
          <lucide.Bot size={24} color="white" />
          {currentScreen === 'teams_chat_list' && (
            <div style={{ position: 'absolute', top: -4, right: -4, width: '12px', height: '12px', backgroundColor: 'var(--nu-red-deep)', borderRadius: '50%', border: '2px solid var(--nu-bg)' }} />
          )}
        </div>
        <div>
          <div style={{ fontFamily: 'var(--font-body)', fontWeight: 600, fontSize: '14px', color: currentScreen === 'teams_chat_list' ? 'var(--nu-text-primary)' : 'var(--nu-text-secondary)' }}>
            NUworks Discovery Bot
          </div>
          <div style={{ fontFamily: 'var(--font-body)', fontSize: '12px', color: currentScreen === 'teams_chat_list' ? 'var(--nu-text-primary)' : 'var(--nu-text-tertiary)', fontWeight: currentScreen === 'teams_chat_list' ? 600 : 400 }}>
            {currentScreen === 'teams_chat_list' ? 'New Discovery Alert available' : 'Active'}
          </div>
        </div>
      </div>

      <div style={{ padding: '12px 16px', display: 'flex', gap: '12px', alignItems: 'center', cursor: 'pointer', backgroundColor: 'var(--nu-bg)' }}>
        <div style={{ width: '40px', height: '40px', borderRadius: '50%', backgroundColor: 'var(--nu-panel)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <span style={{ fontSize: '14px', fontWeight: 600 }}>C</span>
        </div>
        <div>
          <div style={{ fontFamily: 'var(--font-body)', fontWeight: 600, fontSize: '14px' }}>Chris (Advisor)</div>
          <div style={{ fontFamily: 'var(--font-body)', fontSize: '12px', color: 'var(--nu-text-tertiary)' }}>Let me know if you need help.</div>
        </div>
      </div>
    </div>
  </div>
);

const Button = ({ children, variant = 'primary', onClick, disabled, loading, icon: Icon }) => {
  const [isHovered, setIsHovered] = useState(false);
  const [isActive, setIsActive] = useState(false);

  const baseStyle = {
    height: '44px',
    borderRadius: '2px',
    padding: '0 24px',
    fontFamily: 'var(--font-body)',
    fontWeight: 600,
    fontSize: '14px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    cursor: disabled || loading ? 'not-allowed' : 'pointer',
    transition: 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
    border: 'none',
    outline: 'none',
    transform: isActive && !disabled && !loading ? 'scale(0.98)' : 'scale(1)',
    opacity: disabled ? 0.5 : 1,
    width: '100%'
  };

  const variants = {
    primary: {
      backgroundColor: isHovered && !disabled ? 'var(--nu-red-deep)' : 'var(--nu-red)',
      color: '#FFFFFF',
    },
    secondary: {
      backgroundColor: isHovered && !disabled ? 'var(--nu-panel)' : 'transparent',
      color: 'var(--nu-text-primary)',
      border: '1px solid var(--nu-border)'
    }
  };

  return (
    <button
      style={{ ...baseStyle, ...variants[variant] }}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => { setIsHovered(false); setIsActive(false); }}
      onMouseDown={() => setIsActive(true)}
      onMouseUp={() => setIsActive(false)}
      onClick={onClick}
      disabled={disabled || loading}
    >
      {loading ? (
        <motion.div
          animate={{ rotate: 360 }}
          transition={{ repeat: Infinity, duration: 1, ease: "linear" }}
        >
          <lucide.Loader2 size={18} />
        </motion.div>
      ) : (
        <>
          {Icon && <Icon size={18} />}
          {children}
        </>
      )}
    </button>
  );
};

const AdaptiveCard = ({ children }) => (
  <div style={{
    backgroundColor: 'var(--nu-bg)',
    border: '1px solid var(--nu-border)',
    borderRadius: '4px',
    padding: '24px',
    width: '100%',
    maxWidth: '500px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
    display: 'flex',
    flexDirection: 'column',
    gap: '16px'
  }}>
    {children}
  </div>
);

const TypingIndicator = () => (
  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', padding: '12px 16px', color: 'var(--nu-text-tertiary)', fontSize: '12px', fontFamily: 'var(--font-body)' }}>
    <div style={{ display: 'flex', gap: '4px' }}>
      {[0, 1, 2].map(i => (
        <motion.div
          key={i}
          animate={{ y: [0, -4, 0] }}
          transition={{ repeat: Infinity, duration: 0.6, delay: i * 0.15 }}
          style={{ width: '6px', height: '6px', backgroundColor: 'var(--nu-text-tertiary)', borderRadius: '50%' }}
        />
      ))}
    </div>
    NUworks Discovery Bot is typing...
  </div>
);

const SkeletonCard = () => (
  <AdaptiveCard>
    <motion.div
      animate={{ opacity: [0.5, 1, 0.5] }}
      transition={{ repeat: Infinity, duration: 1.5 }}
      style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}
    >
      <div style={{ height: '24px', width: '80%', backgroundColor: 'var(--nu-panel)', borderRadius: '2px' }} />
      <div style={{ height: '16px', width: '100%', backgroundColor: 'var(--nu-panel)', borderRadius: '2px' }} />
      <div style={{ height: '16px', width: '90%', backgroundColor: 'var(--nu-panel)', borderRadius: '2px' }} />
      <div style={{ height: '16px', width: '95%', backgroundColor: 'var(--nu-panel)', borderRadius: '2px' }} />
      <div style={{ height: '44px', width: '100%', backgroundColor: 'var(--nu-panel)', borderRadius: '2px', marginTop: '8px' }} />
    </motion.div>
  </AdaptiveCard>
);

const MessageBubble = ({ sender, content, isCard = false }) => {
  const isBot = sender === 'bot' || sender === 'chris';

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3, ease: "easeOut" }}
      style={{
        display: 'flex',
        flexDirection: isBot ? 'row' : 'row-reverse',
        gap: '12px',
        marginBottom: '24px',
        alignItems: 'flex-start'
      }}
    >
      {isBot && (
        <div style={{ 
          width: '32px', height: '32px', borderRadius: '2px', 
          backgroundColor: sender === 'bot' ? 'var(--nu-red)' : 'var(--nu-panel)', 
          display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 
        }}>
          {sender === 'bot' ? <lucide.Bot size={18} color="white" /> : <span style={{ fontSize: '12px', fontWeight: 600 }}>C</span>}
        </div>
      )}

      <div style={{
        maxWidth: isCard ? '100%' : '70%',
        backgroundColor: isCard ? 'transparent' : (isBot ? 'var(--nu-bg)' : 'var(--nu-surface)'),
        border: isCard ? 'none' : `1px solid ${isBot ? 'var(--nu-border)' : 'transparent'} ग्वालियर`,
        padding: isCard ? '0' : '12px 16px',
        borderRadius: '4px',
        fontFamily: 'var(--font-body)',
        fontSize: '14px',
        color: 'var(--nu-text-primary)',
        lineHeight: 1.5
      }}>
        {sender === 'chris' && <div style={{ fontWeight: 600, marginBottom: '4px', fontSize: '12px', color: 'var(--nu-text-secondary)' }}>Chris (Advisor)</div>}
        {sender === 'bot' && !isCard && <div style={{ fontWeight: 600, marginBottom: '4px', fontSize: '12px', color: 'var(--nu-text-secondary)' }}>NUworks Discovery Bot</div>}
        {content}
      </div>
    </motion.div>
  );
};

// --- MAIN APP ---

const App = () => {
  const [screen, setScreen] = useState('teams_chat_list');
  const [chatHistory, setChatHistory] = useState([]);
  const [isTyping, setIsTyping] = useState(false);
  const [discoveryData, setDiscoveryData] = useState(null);
  const [comparisonData, setComparisonData] = useState(null);
  const [error, setError] = useState(null);
  const messagesEndRef = useRef(null);

  // Auto-scroll
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory, isTyping, screen]);

  // Inject Styles
  useEffect(() => {
    const style = document.createElement('style');
    style.textContent = `
      @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono&family=Open+Sans:wght@400;600&family=Roboto+Condensed:wght@700&display=swap');

      :root {
        --nu-bg: #FFFFFF;
        --nu-surface: #F7F7F7;
        --nu-panel: #F0F0F0;
        --nu-text-primary: #000000;
        --nu-text-secondary: #414141;
        --nu-text-tertiary: #737373;
        --nu-border: #D9D9D9;
        --nu-red: #C8102E;
        --nu-red-deep: #9E0A24;
        --nu-red-tint: #FBE7EA;
        --nu-cream: #F8E5C2;
        --nu-success: #0F8A4B;
        --nu-warning: #B5651D;

        --font-display: 'Roboto Condensed', sans-serif;
        --font-body: 'Open Sans', sans-serif;
        --font-mono: 'IBM Plex Mono', monospace;
      }

      body {
        margin: 0;
        padding: 0;
        background-color: var(--nu-bg);
        color: var(--nu-text-primary);
        font-family: var(--font-body);
        -webkit-font-smoothing: antialiased;
      }

      * { box-sizing: border-box; }

      /* Highlight bold text in AI responses */
      .ai-bold {
        font-weight: 600;
        color: var(--nu-text-primary);
      }
    `;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  // --- AI FETCHERS ---

  const fetchDiscoveryAlert = async () => {
    setIsTyping(true);
    setError(null);
    try {
      const res = await fetch('/api/ai/openai', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
        body: JSON.stringify({
          model: 'gpt-5.5',
          temperature: 0.3,
          messages: [
            {
              role: 'system',
              content: `You are an expert career coach embedded in Microsoft Teams. Rewrite the provided SME job description into a highly persuasive, 3-bullet pitch tailored to the student's interests. Focus on 'Extreme Ownership', hands-on experience, and mentorship. Do not use generic corporate speak. Make it sound like a high-growth tech pitch.

              Return ONLY a JSON object with this exact structure:
              {
                "headline": "String (e.g., Machine Learning Engineer Co-op @ Nebula Metrics (50-person Series A Startup))",
                "bullets": [
                  "String starting with a bold concept like **Extreme Ownership:** ...",
                  "String starting with **Tech Stack:** ...",
                  "String starting with **Mentorship:** ..."
                ]
              }`
            },
            {
              role: 'user',
              content: `Student Major: ${SEED_DATA.student.major}. Interests: ${SEED_DATA.student.interests}. Original JD: ${SEED_DATA.smeJob.originalJD}. Generate the pitch.`
            }
          ]
        })
      });

      const data = await res.json();
      const content = data?.choices?.[0]?.message?.content;
      const parsed = extractJSON(content);

      if (parsed && parsed.headline && parsed.bullets) {
        setDiscoveryData(parsed);
        setScreen('discovery_alert_card');
      } else {
        throw new Error("Invalid AI response format");
      }
    } catch (err) {
      console.error(err);
      setError("Failed to generate alert. Please try again.");
      setScreen('bot_intro_opt_in'); // Revert
    } finally {
      setIsTyping(false);
    }
  };

  const fetchComparison = async () => {
    setIsTyping(true);
    setError(null);
    try {
      const res = await fetch('/api/ai/gemini-compat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
        body: JSON.stringify({
          model: 'gemini-3.1-pro-preview',
          temperature: 0.3,
          max_tokens: 1000,
          messages: [
            {
              role: 'system',
              content: `You are a logical, data-driven career advisor. Compare the startup role to a typical Big Tech intern role side-by-side. Prove logically how the startup offers better immediate hands-on experience to serve as a stepping stone.

              Return ONLY a JSON object with this exact structure:
              {
                "startup_column": {
                  "production_access": "String",
                  "scope": "String",
                  "impact": "String"
                },
                "big_tech_column": {
                  "production_access": "String",
                  "scope": "String",
                  "impact": "String"
                },
                "conclusion": "String (1 sentence summary)"
              }`
            },
            {
              role: 'user',
              content: `Startup Role: ${SEED_DATA.smeJob.title} at ${SEED_DATA.smeJob.company}. Startup Skills: ${SEED_DATA.smeJob.skills}. Student Goal: ${SEED_DATA.student.interests}. Compare this to a typical ${SEED_DATA.bigTech.role} at ${SEED_DATA.bigTech.company}.`
            }
          ]
        })
      });

      const data = await res.json();
      const content = data?.choices?.[0]?.message?.content;
      const parsed = extractJSON(content);

      if (parsed && parsed.startup_column && parsed.big_tech_column) {
        setComparisonData(parsed);
        setScreen('comparison_result');
      } else {
        throw new Error("Invalid AI response format");
      }
    } catch (err) {
      console.error(err);
      setError("Failed to generate comparison. Please try again.");
      setScreen('discovery_alert_card'); // Revert
    } finally {
      setIsTyping(false);
    }
  };

  // --- STATE TRANSITIONS ---

  const handleStartBot = () => {
    setScreen('bot_intro_opt_in');
    setChatHistory([
      {
        id: 1,
        sender: 'chris',
        content: `Hi ${SEED_DATA.student.name}! I know students often tunnel-vision on top-tier companies like Tesla or Google, but there are incredible hidden gems out there. I've set up this bot to find them for you.`
      },
      {
        id: 2,
        sender: 'bot',
        content: `Welcome to NUworks Discovery. I analyze your Canvas/Banner profile to find high-growth startups that match your exact skills. (Data is handled securely under FERPA guidelines).`
      }
    ]);
  };

  const handleConfirmInterests = () => {
    setChatHistory(prev => [...prev, { id: Date.now(), sender: 'user', content: 'Confirm: Machine Learning & AI' }]);
    setScreen('generating_alert_state');
    fetchDiscoveryAlert();
  };

  const handleEditInterests = () => {
    setChatHistory(prev => [
      ...prev, 
      { id: Date.now(), sender: 'user', content: 'Edit Interests' },
      { id: Date.now() + 1, sender: 'bot', content: 'You can update your inferred interests at any time in your NUworks profile settings. For now, shall we proceed with Machine Learning?' }
    ]);
  };

  const handleCompare = () => {
    setChatHistory(prev => [...prev, { id: Date.now(), sender: 'user', content: 'Compare to Big Tech' }]);
    setScreen('generating_comparison_state');
    fetchComparison();
  };

  const handleApply = () => {
    setChatHistory(prev => [...prev, { id: Date.now(), sender: 'user', content: 'Apply on NUworks' }]);
    setScreen('handoff_nuworks');
  };

  // --- RENDER HELPERS ---

  // Helper to render bold text from markdown-like strings
  const renderFormattedText = (text) => {
    const parts = text.split(/(\*\*.*?\*\*)/g);
    return parts.map((part, i) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return <span key={i} className="ai-bold">{part.slice(2, -2)}</span>;
      }
      return part;
    });
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', overflow: 'hidden' }}>
      <Header />

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        <TeamsSidebar />
        <ChatList currentScreen={screen} onSelectBot={handleStartBot} />

        {/* Main Chat Area */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', backgroundColor: 'var(--nu-bg)', position: 'relative' }}>

          {/* Demo Controls */}
          <div style={{ position: 'absolute', top: 16, right: 16, zIndex: 10, display: 'flex', gap: '8px', backgroundColor: 'var(--nu-surface)', padding: '8px', borderRadius: '4px', border: '1px solid var(--nu-border)', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
            <span style={{ fontSize: '10px', fontWeight: 600, alignSelf: 'center', marginRight: '8px', fontFamily: 'var(--font-mono)' }}>DEMO:</span>
            <select 
              aria-label="Select demo screen"
              value={screen} 
              onChange={(e) => setScreen(e.target.value)}
              style={{ fontSize: '12px', padding: '4px', fontFamily: 'var(--font-mono)', border: '1px solid var(--nu-border)', borderRadius: '2px' }}
            >
              <option value="teams_chat_list">1. Chat List</option>
              <option value="bot_intro_opt_in">2. Intro & Opt-in</option>
              <option value="generating_alert_state">3. Generating Alert</option>
              <option value="discovery_alert_card">4. Alert Card</option>
              <option value="generating_comparison_state">5. Generating Comparison</option>
              <option value="comparison_result">6. Comparison Result</option>
              <option value="handoff_nuworks">7. Handoff</option>
            </select>
          </div>

          {screen === 'teams_chat_list' ? (
            <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', color: 'var(--nu-text-tertiary)', gap: '16px' }}>
              <lucide.MessageSquare size={48} strokeWidth={1} />
              <div style={{ fontFamily: 'var(--font-display)', fontSize: '24px', color: 'var(--nu-text-secondary)' }}>Select a chat to start messaging</div>
            </div>
          ) : (
            <>
              {/* Chat Feed */}
