// --- MAIN APP ---

const App = () => {
  const [screen, setScreen] = useState('teams_chat_list');
  const [chatHistory, setChatHistory] = useState([]);
  const [isTyping, setIsTyping] = useState(false);
  const [discoveryData, setDiscoveryData] = useState(null);
  const [comparisonData, setComparisonData] = useState(null);
  const [error, setError] = useState(null);
  const messagesEndRef = useRef(null);

  // Auto-scroll
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory, isTyping, screen]);

  // Inject Styles
  useEffect(() => {
    const style = document.createElement('style');
    style.textContent = `
      @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono&family=Open+Sans:wght@400;600&family=Roboto+Condensed:wght@700&display=swap');

      :root {
        --nu-bg: #FFFFFF;
        --nu-surface: #F7F7F7;
        --nu-panel: #F0F0F0;
        --nu-text-primary: #000000;
        --nu-text-secondary: #414141;
        --nu-text-tertiary: #737373;
        --nu-border: #D9D9D9;
        --nu-red: #C8102E;
        --nu-red-deep: #9E0A24;
        --nu-red-tint: #FBE7EA;
        --nu-cream: #F8E5C2;
        --nu-success: #0F8A4B;
        --nu-warning: #B5651D;

        --font-display: 'Roboto Condensed', sans-serif;
        --font-body: 'Open Sans', sans-serif;
        --font-mono: 'IBM Plex Mono', monospace;
      }

      body {
        margin: 0;
        padding: 0;
        background-color: var(--nu-bg);
        color: var(--nu-text-primary);
        font-family: var(--font-body);
        -webkit-font-smoothing: antialiased;
      }

      * { box-sizing: border-box; }

      /* Highlight bold text in AI responses */
      .ai-bold {
        font-weight: 600;
        color: var(--nu-text-primary);
      }
    `;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  // --- AI FETCHERS ---

  const fetchDiscoveryAlert = async () => {
    setIsTyping(true);
    setError(null);
    try {
      const res = await fetch('/api/ai/openai', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
        body: JSON.stringify({
          model: 'gpt-5.5',
          temperature: 0.3,
          messages: [
            {
              role: 'system',
              content: `You are an expert career coach embedded in Microsoft Teams. Rewrite the provided SME job description into a highly persuasive, 3-bullet pitch tailored to the student's interests. Focus on 'Extreme Ownership', hands-on experience, and mentorship. Do not use generic corporate speak. Make it sound like a high-growth tech pitch.

              Return ONLY a JSON object with this exact structure:
              {
                "headline": "String (e.g., Machine Learning Engineer Co-op @ Nebula Metrics (50-person Series A Startup))",
                "bullets": [
                  "String starting with a bold concept like **Extreme Ownership:** ...",
                  "String starting with **Tech Stack:** ...",
                  "String starting with **Mentorship:** ..."
                ]
              }`
            },
            {
              role: 'user',
              content: `Student Major: ${SEED_DATA.student.major}. Interests: ${SEED_DATA.student.interests}. Original JD: ${SEED_DATA.smeJob.originalJD}. Generate the pitch.`
            }
          ]
        })
      });

      const data = await res.json();
      const content = data?.choices?.[0]?.message?.content;
      const parsed = extractJSON(content);

      if (parsed && parsed.headline && parsed.bullets) {
        setDiscoveryData(parsed);
        setScreen('discovery_alert_card');
      } else {
        throw new Error("Invalid AI response format");
      }
    } catch (err) {
      console.error(err);
      setError("Failed to generate alert. Please try again.");
      setScreen('bot_intro_opt_in'); // Revert
    } finally {
      setIsTyping(false);
    }
  };

  const fetchComparison = async () => {
    setIsTyping(true);
    setError(null);
    try {
      const res = await fetch('/api/ai/gemini-compat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
        body: JSON.stringify({
          model: 'gemini-3.1-pro-preview',
          temperature: 0.3,
          max_tokens: 1000,
          messages: [
            {
              role: 'system',
              content: `You are a logical, data-driven career advisor. Compare the startup role to a typical Big Tech intern role side-by-side. Prove logically how the startup offers better immediate hands-on experience to serve as a stepping stone.

              Return ONLY a JSON object with this exact structure:
              {
                "startup_column": {
                  "production_access": "String",
                  "scope": "String",
                  "impact": "String"
                },
                "big_tech_column": {
                  "production_access": "String",
                  "scope": "String",
                  "impact": "String"
                },
                "conclusion": "String (1 sentence summary)"
              }`
            },
            {
              role: 'user',
              content: `Startup Role: ${SEED_DATA.smeJob.title} at ${SEED_DATA.smeJob.company}. Startup Skills: ${SEED_DATA.smeJob.skills}. Student Goal: ${SEED_DATA.student.interests}. Compare this to a typical ${SEED_DATA.bigTech.role} at ${SEED_DATA.bigTech.company}.`
            }
          ]
        })
      });

      const data = await res.json();
      const content = data?.choices?.[0]?.message?.content;
      const parsed = extractJSON(content);

      if (parsed && parsed.startup_column && parsed.big_tech_column) {
        setComparisonData(parsed);
        setScreen('comparison_result');
      } else {
        throw new Error("Invalid AI response format");
      }
    } catch (err) {
      console.error(err);
      setError("Failed to generate comparison. Please try again.");
      setScreen('discovery_alert_card'); // Revert
    } finally {
      setIsTyping(false);
    }
  };

  // --- STATE TRANSITIONS ---

  const handleStartBot = () => {
    setScreen('bot_intro_opt_in');
    setChatHistory([
      {
        id: 1,
        sender: 'chris',
        content: `Hi ${SEED_DATA.student.name}! I know students often tunnel-vision on top-tier companies like Tesla or Google, but there are incredible hidden gems out there. I've set up this bot to find them for you.`
      },
      {
        id: 2,
        sender: 'bot',
        content: `Welcome to NUworks Discovery. I analyze your Canvas/Banner profile to find high-growth startups that match your exact skills. (Data is handled securely under FERPA guidelines).`
      }
    ]);
  };

  const handleConfirmInterests = () => {
    setChatHistory(prev => [...prev, { id: Date.now(), sender: 'user', content: 'Confirm: Machine Learning & AI' }]);
    setScreen('generating_alert_state');
    fetchDiscoveryAlert();
  };

  const handleEditInterests = () => {
    setChatHistory(prev => [
      ...prev, 
      { id: Date.now(), sender: 'user', content: 'Edit Interests' },
      { id: Date.now() + 1, sender: 'bot', content: 'You can update your inferred interests at any time in your NUworks profile settings. For now, shall we proceed with Machine Learning?' }
    ]);
  };

  const handleCompare = () => {
    setChatHistory(prev => [...prev, { id: Date.now(), sender: 'user', content: 'Compare to Big Tech' }]);
    setScreen('generating_comparison_state');
    fetchComparison();
  };

  const handleApply = () => {
    setChatHistory(prev => [...prev, { id: Date.now(), sender: 'user', content: 'Apply on NUworks' }]);
    setScreen('handoff_nuworks');
  };

  // --- RENDER HELPERS ---

  // Helper to render bold text from markdown-like strings
  const renderFormattedText = (text) => {
    const parts = text.split(/(\*\*.*?\*\*)/g);
    return parts.map((part, i) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return <span key={i} className="ai-bold">{part.slice(2, -2)}</span>;
      }
      return part;
    });
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', overflow: 'hidden' }}>
      <Header />

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        <TeamsSidebar />
        <ChatList currentScreen={screen} onSelectBot={handleStartBot} />

        {/* Main Chat Area */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', backgroundColor: 'var(--nu-bg)', position: 'relative' }}>

          {/* Demo Controls */}
          <div style={{ position: 'absolute', top: 16, right: 16, zIndex: 10, display: 'flex', gap: '8px', backgroundColor: 'var(--nu-surface)', padding: '8px', borderRadius: '4px', border: '1px solid var(--nu-border)', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
            <span style={{ fontSize: '10px', fontWeight: 600, alignSelf: 'center', marginRight: '8px', fontFamily: 'var(--font-mono)' }}>DEMO:</span>
            <select 
              aria-label="Select demo screen"
              value={screen} 
              onChange={(e) => setScreen(e.target.value)}
              style={{ fontSize: '12px', padding: '4px', fontFamily: 'var(--font-mono)', border: '1px solid var(--nu-border)', borderRadius: '2px' }}
            >
              <option value="teams_chat_list">1. Chat List</option>
              <option value="bot_intro_opt_in">2. Intro & Opt-in</option>
              <option value="generating_alert_state">3. Generating Alert</option>
              <option value="discovery_alert_card">4. Alert Card</option>
              <option value="generating_comparison_state">5. Generating Comparison</option>
              <option value="comparison_result">6. Comparison Result</option>
              <option value="handoff_nuworks">7. Handoff</option>
            </select>
          </div>

          {screen === 'teams_chat_list' ? (
            <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', color: 'var(--nu-text-tertiary)', gap: '16px' }}>
              <lucide.MessageSquare size={48} strokeWidth={1} />
              <div style={{ fontFamily: 'var(--font-display)', fontSize: '24px', color: 'var(--nu-text-secondary)' }}>Select a chat to start messaging</div>
            </div>
          ) : (
            <>
              {/* Chat Feed */}
              <div style={{ flex: 1, overflowY: 'auto', padding: '24px 48px' }}>
                {chatHistory.map(msg => (
                  <MessageBubble key={msg.id} sender={msg.sender} content={msg.content} />
                ))}

                {/* State-specific UI injected into feed */}

                {screen === 'bot_intro_opt_in' && (
                  <MessageBubble sender="bot" isCard content={
                    <AdaptiveCard>
                      <div style={{ fontFamily: 'var(--font-body)', fontSize: '14px' }}>
                        I see your focus is <strong>Machine Learning</strong>. Ready for your first Discovery Alert?
                      </div>
                      <div style={{ display: 'flex', gap: '12px', marginTop: '8px' }}>
                        <Button onClick={handleConfirmInterests}>Confirm: Machine Learning & AI</Button>
                        <Button variant="secondary" onClick={handleEditInterests}>Edit Interests</Button>
                      </div>
                    </AdaptiveCard>
                  } />
                )}

                {screen === 'generating_alert_state' && (
                  <SkeletonCard />
                )}

                {screen === 'discovery_alert_card' && discoveryData && (
                  <MessageBubble sender="bot" isCard content={
                    <AdaptiveCard>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--nu-red)', fontWeight: 600, fontSize: '12px', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                        <lucide.Sparkles size={14} /> Weekly Discovery Alert
                      </div>
                      <h3 style={{ fontFamily: 'var(--font-display)', fontSize: '24px', margin: '0 0 8px 0', lineHeight: 1.2 }}>
                        {discoveryData.headline}
                      </h3>
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                        {discoveryData.bullets.map((bullet, i) => (
                          <motion.div 
                            key={i}
                            initial={{ opacity: 0, x: -10 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ delay: i * 0.15, duration: 0.4 }}
                            style={{ display: 'flex', gap: '12px', alignItems: 'flex-start' }}
                          >
                            <div style={{ width: '6px', height: '6px', borderRadius: '50%', backgroundColor: 'var(--nu-red)', marginTop: '8px', flexShrink: 0 }} />
                            <div style={{ fontSize: '14px', lineHeight: 1.5 }}>
                              {renderFormattedText(bullet)}
                            </div>
                          </motion.div>
                        ))}
                      </div>
                      <div style={{ display: 'flex', gap: '12px', marginTop: '16px' }}>
                        <Button onClick={handleCompare} icon={lucide.Scale}>Compare to Big Tech</Button>
                        <Button variant="secondary" onClick={handleApply}>Apply on NUworks</Button>
                      </div>
                    </AdaptiveCard>
                  } />
                )}

                {screen === 'generating_comparison_state' && (
                  <div style={{ padding: '24px', backgroundColor: 'var(--nu-surface)', borderRadius: '4px', border: '1px dashed var(--nu-border)', display: 'flex', alignItems: 'center', gap: '12px', color: 'var(--nu-text-secondary)' }}>
                    <motion.div animate={{ rotate: 360 }} transition={{ repeat: Infinity, duration: 2, ease: "linear" }}>
                      <lucide.Cpu size={20} />
                    </motion.div>
                    <span style={{ fontFamily: 'var(--font-mono)', fontSize: '12px' }}>Analyzing Nebula Metrics vs. typical Mega-Corp ML roles...</span>
                  </div>
                )}

                {screen === 'comparison_result' && comparisonData && (
                  <MessageBubble sender="bot" isCard content={
                    <AdaptiveCard>
                      <h3 style={{ fontFamily: 'var(--font-display)', fontSize: '20px', margin: 0 }}>
                        Startup vs. Big Tech Comparison
                      </h3>
                      <p style={{ fontSize: '14px', color: 'var(--nu-text-secondary)', margin: '0 0 16px 0' }}>
                        Based on your goal of hands-on model deployment:
                      </p>

                      <div style={{ display: 'flex', gap: '16px', backgroundColor: 'var(--nu-surface)', padding: '16px', borderRadius: '2px' }}>
                        <div style={{ flex: 1 }}>
                          <div style={{ fontWeight: 700, fontFamily: 'var(--font-display)', fontSize: '16px', color: 'var(--nu-red)', marginBottom: '12px', borderBottom: '2px solid var(--nu-red)', paddingBottom: '4px' }}>
                            {SEED_DATA.smeJob.company}
                          </div>
                          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', fontSize: '13px' }}>
                            <div><strong>Production Access:</strong> {comparisonData.startup_column.production_access}</div>
                            <div><strong>Scope:</strong> {comparisonData.startup_column.scope}</div>
                            <div><strong>Impact:</strong> {comparisonData.startup_column.impact}</div>
                          </div>
                        </div>
                        <div style={{ width: '1px', backgroundColor: 'var(--nu-border)' }} />
                        <div style={{ flex: 1 }}>
                          <div style={{ fontWeight: 700, fontFamily: 'var(--font-display)', fontSize: '16px', color: 'var(--nu-text-secondary)', marginBottom: '12px', borderBottom: '2px solid var(--nu-border)', paddingBottom: '4px' }}>
                            Typical {SEED_DATA.bigTech.company} Intern
                          </div>
                          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', fontSize: '13px', color: 'var(--nu-text-secondary)' }}>
                            <div><strong>Production Access:</strong> {comparisonData.big_tech_column.production_access}</div>
                            <div><strong>Scope:</strong> {comparisonData.big_tech_column.scope}</div>
                            <div><strong>Impact:</strong> {comparisonData.big_tech_column.impact}</div>
                          </div>
                        </div>
                      </div>

                      <div style={{ backgroundColor: 'var(--nu-cream)', padding: '12px', borderRadius: '2px', fontSize: '14px', fontWeight: 600, display: 'flex', gap: '12px', alignItems: 'flex-start' }}>
                        <lucide.Lightbulb size={18} color="var(--nu-warning)" style={{ flexShrink: 0, marginTop: '2px' }} />
                        <div>{comparisonData.conclusion}</div>
                      </div>

                      <div style={{ marginTop: '8px' }}>
                        <Button onClick={handleApply} icon={lucide.ExternalLink}>Apply on NUworks</Button>
                      </div>
                    </AdaptiveCard>
                  } />
                )}

                {screen === 'handoff_nuworks' && (
                  <MessageBubble sender="bot" isCard content={
                    <AdaptiveCard>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '12px', color: 'var(--nu-success)' }}>
                        <div style={{ width: '32px', height: '32px', borderRadius: '50%', backgroundColor: 'rgba(15, 138, 75, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                          <lucide.Check size={20} />
                        </div>
                        <h3 style={{ fontFamily: 'var(--font-display)', fontSize: '20px', margin: 0, color: 'var(--nu-text-primary)' }}>
                          Great choice, Alex!
                        </h3>
                      </div>
                      <p style={{ fontSize: '14px', margin: 0 }}>
                        I've saved this role to your NUworks dashboard. Click below to complete your application. Good luck!
                      </p>
                      <Button onClick={() => setScreen('teams_chat_list')} variant="secondary">Return to Chat</Button>
                    </AdaptiveCard>
                  } />
                )}

                {error && (
                  <div style={{ padding: '12px', backgroundColor: 'var(--nu-red-tint)', color: 'var(--nu-red-deep)', borderRadius: '4px', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '24px' }}>
                    <lucide.AlertCircle size={16} /> {error}
                  </div>
                )}

                {isTyping && <TypingIndicator />}
                <div ref={messagesEndRef} />
              </div>

              {/* Chat Input Area */}
              <div style={{ padding: '16px 24px', borderTop: '1px solid var(--nu-border)', backgroundColor: 'var(--nu-bg)' }}>
                <div style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  backgroundColor: 'var(--nu-surface)', 
                  border: '1px solid var(--nu-border)', 
                  borderRadius: '4px',
                  padding: '8px 16px',
                  gap: '12px'
                }}>
                  <lucide.Plus size={20} color="var(--nu-text-tertiary)" />
                  <input 
                    type="text" 
                    aria-label="Type a new message"
                    placeholder="Type a new message..." 
                    disabled={isTyping || screen === 'handoff_nuworks'}
                    style={{ 
                      flex: 1, 
                      border: 'none', 
                      backgroundColor: 'transparent', 
                      outline: 'none', 
                      fontFamily: 'var(--font-body)', 
                      fontSize: '14px',
                      color: 'var(--nu-text-primary)'
                    }} 
                  />
                  <div style={{ display: 'flex', gap: '8px', color: 'var(--nu-text-tertiary)' }}>
                    <lucide.Smile size={20} />
                    <lucide.Paperclip size={20} />
                    <lucide.Send size={20} color={isTyping ? 'var(--nu-text-tertiary)' : 'var(--nu-red)'} style={{ cursor: isTyping ? 'not-allowed' : 'pointer' }} />
                  </div>
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

// Verification block
function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}
